async function api(path,opts){opts=opts||{};var headers={"Accept":"application/json","Authorization":"Bearer "+token};if(opts.body!==undefined){headers["Content-Type"]="application/json";}if(opts.headers)Object.keys(opts.headers).forEach(function(k){headers[k]=opts.headers[k];});var res;try{res=await fetch(API+path,{method:opts.method||"GET",headers:headers,body:opts.body===undefined?undefined:JSON.stringify(opts.body),credentials:"omit"});}catch(e){throw new Error("Aurelink could not be reached. Check your connection and retry.");}var data={};try{data=await res.json();}catch(e){}if(res.status===401){sessionStorage.removeItem("aurelink.accessToken");sessionStorage.removeItem("aurelink.refreshToken");location.replace("/?next=/portal.html");throw new Error("Your session expired. Sign in again.");}if(!res.ok||data.success===false)throw new Error(data.message||"Aurelink could not complete this request.");return data;}
