function apiKeysPage(){var rows=state.apiKeys.map(function(k){var expired=k.expires_at&&new Date(k.expires_at)<new Date(),revoked=!!k.revoked_at;var actions=revoked||expired?"—":'<div class="row-actions"><button class="text-btn" data-key-rotate="'+esc(k.id)+'">Rotate</button><button class="text-btn" data-key-revoke="'+esc(k.id)+'">Revoke</button></div>';return '<tr><td><strong>'+esc(k.label)+'</strong><div class="subtle">'+esc(k.key_prefix||"")+'</div></td><td>'+esc(k.environment)+'</td><td>'+esc(k.project_name||"Account-wide")+'</td><td>'+esc((k.scopes||[]).join(", "))+'</td><td>'+Number(k.rate_limit_per_minute||0).toLocaleString()+'/min</td><td>'+fmt(k.created_at)+'</td><td>'+fmt(k.last_used_at)+'</td><td>'+fmt(k.expires_at)+'</td><td>'+status(revoked?"revoked":expired?"expired":"active")+'</td><td>'+actions+'</td></tr>';});return head("API keys","Create and manage test and live credentials. Secret values are shown only once when issued or rotated.")+panel("Credentials",'<div class="toolbar"><button class="btn small" id="new-api-key">Create API key</button></div>'+table(["Key","Environment","Project","Permissions","Rate limit","Created","Last used","Expires","Status","Actions"],rows,"No API keys created.")+'<div id="key-editor"></div>',"Aurelink stores a hash of each secret. Never share a live key in client-side code.")+panel("Documented permissions",'<div class="detail-list"><div class="detail-row"><span>communications:read</span><b>Read message and usage data</b></div><div class="detail-row"><span>communications:send</span><b>Send SMS and email</b></div><div class="detail-row"><span>verify:write</span><b>Create and validate OTP sessions</b></div></div>',"The UI offers the documented public API permission set.");}
function apiLogsPage(){var u=state.devUsage||{},daily=safeArray(u,"daily"),rows=state.apiLogs.map(function(l){return '<tr><td><strong>'+esc(l.method)+'</strong></td><td>'+esc(l.path)+'</td><td>'+esc(l.environment)+'</td><td>'+status(l.status_code>=400?"failed":"success")+' '+esc(l.status_code)+'</td><td>'+esc(l.latency_ms)+' ms</td><td>'+esc(l.request_id||"—")+'</td><td>'+fmt(l.created_at)+'</td></tr>';});return head("API request logs","Inspect authenticated API traffic, request IDs, HTTP results and latency.")+ '<div class="grid stats">'+stat("30-day requests",Number((daily||[]).reduce(function(a,x){return a+Number(x.requests||0);},0)).toLocaleString(),"Recorded API requests","≋")+stat("30-day errors",Number((daily||[]).reduce(function(a,x){return a+Number(x.errors||0);},0)).toLocaleString(),"HTTP 4xx and 5xx","!")+stat("Active keys",Number(state.apiKeys.filter(function(k){return !k.revoked_at&&(!k.expires_at||new Date(k.expires_at)>new Date());}).length),"Key usage summary","⌘")+stat("Usage window",String(u.days||30)+" days","Backend reporting period","◷")+'</div>'+panel("Recent API requests",'<div class="toolbar"><input id="api-log-search" placeholder="Search path or request ID"><select id="api-log-env"><option value="">All environments</option><option value="test">Test</option><option value="live">Live</option></select><select id="api-log-status"><option value="">All statuses</option><option value="error">Errors only</option><option value="success">Successful only</option></select></div><div id="api-log-table">'+table(["Method","Path","Environment","HTTP status","Latency","Request ID","Created"],rows,"No API requests recorded.")+'</div>',"The list shows the latest 100 request records.");}
