function accountPage(){var a=state.account||{},u=a.user||{},sec=a.security||{},sessions=state.sessions.map(function(x){return '<tr><td><strong>'+esc(x.device_name||x.device_id||"Device")+'</strong><div class="subtle">'+esc([x.platform,x.browser].filter(Boolean).join(" · "))+'</div></td><td>'+esc(x.ip_address||"—")+'</td><td>'+esc([x.city,x.region,x.country].filter(Boolean).join(", ")||"—")+'</td><td>'+fmt(x.last_activity_at||x.created_at)+'</td><td>'+status(x.revoked_at?"revoked":x.current?"current":"active")+'</td><td>'+(x.current||x.revoked_at?"—":'<button class="text-btn" data-session-revoke="'+esc(x.id)+'">Revoke</button>')+'</td></tr>';});var events=state.loginActivity.map(function(x){return '<tr><td>'+esc(x.event_type||"—")+'</td><td>'+status(x.success?"success":"failed")+'</td><td>'+esc(x.ip_address||"—")+'</td><td>'+esc([x.city,x.region,x.country].filter(Boolean).join(", ")||"—")+'</td><td>'+fmt(x.created_at)+'</td></tr>';});return head("Account & security","Review account verification and active sessions. Existing profile and authentication settings remain unchanged.")+panel("Account profile",'<div class="detail-list"><div class="detail-row"><span>Name</span><b>'+esc([u.first_name,u.last_name].filter(Boolean).join(" ")||"—")+'</b></div><div class="detail-row"><span>Email</span><b>'+esc(u.email||"—")+'</b></div><div class="detail-row"><span>Email verification</span><b>'+status(u.email_verified?"verified":"unverified")+'</b></div><div class="detail-row"><span>Country verification</span><b>'+status(u.country_verified_at?"verified":u.country_code?"pending":"not provided")+'</b></div><div class="detail-row"><span>Account status</span><b>'+status(u.account_status||"unknown")+'</b></div><div class="detail-row"><span>Two-factor authentication</span><b>'+status(sec.two_factor_enabled?"enabled":"not enabled")+'</b></div><div class="detail-row"><span>Created</span><b>'+fmt(u.created_at)+'</b></div><div class="detail-row"><span>Last sign-in</span><b>'+fmt(u.last_login_at)+'</b></div></div>',"Profile details are read from the authenticated account endpoint.")+panel("Active sessions",'<div class="toolbar"><button class="btn secondary small" id="revoke-other-sessions">Sign out other sessions</button></div>'+table(["Device","IP address","Location","Last activity","Status","Action"],sessions,"No active sessions."),"Manage sessions without changing login or password flows.")+panel("Login activity",table(["Event","Result","IP address","Location","Time"],events,"No login activity recorded."),"Recent account sign-in history.");}
function channelOverviewPage(channel){var o=state.channelOverview||{},groups=safeArray(o,"messages").filter(function(x){return x.channel===channel;}),usage=safeArray(o,"usage").filter(function(x){return x.channel===channel;}),messages=state.channelMessages||[];var counts={total:0,accepted:0,delivered:0,failed:0,pending:0,queued:0,units:0};groups.forEach(function(x){var n=Number(x.total||0),st=String(x.status||"").toLowerCase();counts.total+=n;if(st==="accepted")counts.accepted+=n;if(st==="delivered")counts.delivered+=n;if(["failed","bounced","rejected"].indexOf(st)>=0)counts.failed+=n;if(["pending","deferred"].indexOf(st)>=0)counts.pending+=n;if(["queued","processing"].indexOf(st)>=0)counts.queued+=n;});usage.forEach(function(x){counts.units+=Number(x.units||0);});var recent=messages.map(function(m){return '<tr><td><strong>'+esc(m.recipient)+'</strong><div class="subtle">'+esc(m.subject||m.category||"")+'</div></td><td>'+esc(m.provider||"—")+'</td><td>'+status(m.status)+'</td><td>'+esc(m.provider_message_id||"—")+'</td><td>'+fmt(m.created_at)+'</td></tr>';});var usageRows=usage.map(function(x){return '<tr><td>'+esc(x.status)+'</td><td>'+Number(x.messages||0).toLocaleString()+'</td><td>'+Number(x.units||0).toLocaleString()+'</td><td>'+money(x.metered_amount_minor,x.currency)+'</td></tr>';});return head(channel==="sms"?"SMS overview":"Email overview",channel==="sms"?"Review SMS delivery, segment usage and the configured provider route.":"Review email delivery, credit usage and the configured provider route.",'<button class="btn" data-view="'+(channel==="sms"?"sms":"email")+'">Compose '+(channel==="sms"?"SMS":"email")+'</button>')+'<div class="grid stats">'+stat("Total messages",counts.total.toLocaleString(),"Last 30 days","≋")+stat("Accepted",counts.accepted.toLocaleString(),"Accepted by Aurelink/provider","✓")+stat("Delivered",counts.delivered.toLocaleString(),"Provider-confirmed","✓")+stat("Failed",counts.failed.toLocaleString(),"Failed or bounced","!")+'</div><div class="grid stats">'+stat("Pending",counts.pending.toLocaleString(),"Awaiting provider outcome","◷")+stat("Queued",counts.queued.toLocaleString(),"Queued or processing","↗")+stat(channel==="sms"?"Billable segments":"Email units",counts.units.toLocaleString(),"Recorded usage units","▤")+stat("Provider route",esc((o.providers||{})[channel]||"Aurelink-managed"),"Selected by server configuration","⌘")+'</div>'+panel("Recent "+channel.toUpperCase()+" activity",table(["Recipient","Provider","Status","Provider message ID","Created"],recent,"No messages recorded for this channel."),"The provider message ID is populated when returned by the delivery adapter.")+panel(channel.toUpperCase()+" usage breakdown",table(["Status","Messages","Units","Metered amount"],usageRows,"No usage records for this channel."),"Usage and billing data are returned by the communications backend.");}
function page(){switch(state.view){case"overview":return overviewPage();case"sms-overview":return channelOverviewPage("sms");case"email-overview":return channelOverviewPage("email");case"phone":return phonePage();case"esim":return esimPage();case"projects":return projectsPage();case"api-keys":return apiKeysPage();case"api-logs":return apiLogsPage();case"sdks":return sdksPage();case"team":return teamPage();case"account":return accountPage();case"sms":return smsPage();case"email":return emailPage();case"activity":return activityPage();case"templates":return templatesPage();case"contacts":return contactsPage();case"campaigns":return campaignsPage();case"verify":return verifyPage();case"domains":return domainsPage();case"senders":return sendersPage();case"smtp":return smtpPage();case"senderids":return senderIdsPage();case"developer":return developerPage();case"billing":return billingPage();case"reputation":return reputationPage();default:return overviewPage();}}
function render(){app.innerHTML=shell(page());}
function val(id){var e=document.getElementById(id);return e?e.value.trim():"";}
function fileAsBase64(file){return new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(){var value=String(reader.result||"");resolve(value.split(",").pop());};reader.onerror=function(){reject(new Error("Could not read attachment: "+file.name));};reader.readAsDataURL(file);});}

